func (sr *targetStatus) getStatus(targetName string) (int, bool) {
	sr.Lock()
	defer sr.Unlock()
	status, exists := sr.statusRegistry[targetName]
	return status, exists
}

func (sr *targetStatus) setStatus(targetName string, status int) {
	sr.Lock()
	defer sr.Unlock()
	sr.statusRegistry[targetName] = status
}

